pool, layers = {}, []
def drop(term, doc): pool[term] = doc
def freeze(): layers.append(dict(sorted(pool.items()))); pool.clear()
for t in ["b", "a", "c"]: drop(t, 1)
freeze()
for t in ["e", "d"]: drop(t, 2)
freeze()
print("sediment layers:", len(layers), "| terms:", [list(l) for l in layers])
assert len(layers) == 2

docs = [("news", 2024), ("blog", 2024), ("news", 2023)]
banners = {}
for i, (c, y) in enumerate(docs):
    for key in [("cat", c), ("yr", y)]:
        b = banners.setdefault(key, [0]*len(docs)); b[i] = 1
both = [a & b for a, b in zip(banners[("cat", "news")], banners[("yr", 2024)])]
print("news AND 2024:", both)
assert both == [1, 0, 0]

trail = {"planets": [1, 2, 3]}
