mirror = {1: ["red", "planet", "mars"], 2: ["blue", "planet", "earth"]}
def snippet(doc, word):
    return " ".join(f"<<{w}>>" if w == word else w for w in mirror[doc])
print(snippet(1, "planet"))
assert snippet(1, "planet") == "red <<planet>> mars"

rec = {"title": ["mars", "rover"], "body": ["the", "rover", "landed", "on", "mars", "today"]}
volume = {"title": 4.0, "body": 1.0}
score = sum(rec[f].count("mars") * volume[f] for f in rec)
print("title-first score:", score)
assert score == 5.0

tree = {}
def plant(w):
    n = tree
    for ch in w: n = n.setdefault(ch, {})
    n["*"] = True
def gather(prefix):
    n = tree
    for ch in prefix: n = n.get(ch, {})
    out = []
    def walk(m, s):
        if "*" in m: out.append(s)
        for ch, c in m.items():
            if ch != "*": walk(c, s+ch)
    walk(n, prefix); return out
for w in ["mars", "marsh", "moon"]: plant(w)
print("prefix 'mar':", gather("mar"))
assert gather("mar") == ["mars", "marsh"]
